{
  "name": "六自由度遥操作游戏手柄",
  "name_en": "6-DOF Teleoperation Gamepad",
  "manufacturer": "",
  "description": "一种手持式游戏控制器，用作实验室机器人遥操作的人机输入设备。它通过摇杆、扳机、肩键和按键将操作者的输入映射为六自由度位姿增量指令，并可用于控制夹爪开合，常用于机械臂或末端执行器的手动示教与实时遥控。",
  "description_en": "A handheld game controller used as a human input device for robot teleoperation in the lab. Joysticks, triggers, bumpers, and buttons are mapped to 6-degree-of-freedom motion increments and gripper control, making it suitable for manual teaching and real-time control of a robot arm or end effector.",
  "tag_hints": [
    "robot teleoperation",
    "6-DOF control",
    "gamepad input",
    "manual teaching",
    "gripper control",
    "human-machine interface"
  ],
  "actions": [
    {
      "action_name": "auto-calibrate",
      "description": "校准手柄（通常无需额外校准）",
      "description_en": "Calibrate the gamepad (typically no extra calibration is required)."
    },
    {
      "action_name": "auto-configure",
      "description": "配置手柄（通常无需额外配置）",
      "description_en": "Configure the gamepad (typically no additional configuration is required)."
    },
    {
      "action_name": "auto-connect",
      "description": "连接手柄",
      "description_en": "Connect the gamepad."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开手柄连接",
      "description_en": "Disconnect the gamepad."
    },
    {
      "action_name": "auto-is_calibrated",
      "description": "检查手柄是否已校准",
      "description_en": "Check whether the gamepad is calibrated."
    },
    {
      "action_name": "auto-is_connected",
      "description": "检查手柄是否已连接",
      "description_en": "Check whether the gamepad is connected."
    },
    {
      "action_name": "auto-send_feedback",
      "description": "向手柄发送反馈（该设备通常不支持反馈）",
      "description_en": "Send feedback to the gamepad (this device typically does not support feedback)."
    },
    {
      "action_name": "auto-action_features",
      "description": "获取动作特性定义",
      "description_en": "Get the action feature definition."
    },
    {
      "action_name": "auto-feedback_features",
      "description": "获取反馈特性定义",
      "description_en": "Get the feedback feature definition."
    },
    {
      "action_name": "auto-get_action",
      "description": "获取当前手柄遥操作动作指令",
      "description_en": "Get the current teleoperation action command from the gamepad."
    }
  ]
}

